// Junta lo que trajo Google en un texto corto para el modelo
// y guarda los tres primeros enlaces para la página.
const r = $input.first().json
const form = $('Formulario').first().json
const lista = (r.organic_results || []).slice(0, 6)
const renglones = lista.map(function (x, i) {
  return (i + 1) + '. ' + x.title + ' (' + (x.source || x.link) + '): ' + (x.snippet || '')
})
return [{
  json: {
    nombre: form.nombre.trim(),
    idea: (form.idea || '').trim(),
    cantidad: lista.length,
    resultados: renglones.length ? renglones.join('\n') : 'Google no encontró nada con ese nombre exacto.',
    enlaces: lista.slice(0, 3).map(function (x) { return { titulo: x.title, enlace: x.link } })
  }
}]

// Arma la página del veredicto con lo que dijo el modelo y los enlaces de Google.
// Pensada para proyectar a 1920 x 1080: el nombre, el veredicto y por qué se ven sin bajar.
// Todo va adentro: ni fuentes, ni imágenes, ni scripts de otro servidor.

// Todo texto que viene de afuera pasa por acá antes de entrar al HTML.
function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}
// Solo enlaces web de verdad.
function enlaceSeguro(url) {
  return /^https?:\/\//i.test(String(url || '')) ? String(url) : ''
}
// El sitio de un enlace, sin www.
function sitio(url) {
  const m = String(url || '').match(/^https?:\/\/([^/?#]+)/i)
  return m ? m[1].replace(/^www\./i, '') : ''
}
// Busca una línea del estilo CLAVE: valor en la respuesta del modelo.
function linea(texto, clave) {
  const m = texto.match(new RegExp(clave + '\\s*:\\s*(.+)', 'i'))
  return m ? m[1].trim() : ''
}
// Un SVG chico como imagen de fondo, sin pedir nada afuera.
function svgUrl(svg) {
  return 'url("data:image/svg+xml,' + encodeURIComponent(svg).replace(/\(/g, '%28').replace(/\)/g, '%29').replace(/'/g, '%27') + '")'
}

const CIRCUITO = svgUrl("<svg xmlns='http://www.w3.org/2000/svg' width='440' height='260' viewBox='0 0 440 260' fill='none' stroke='#4DA3FF' stroke-opacity='0.32' stroke-width='2'><path d='M0 70H120L160 30H330'/><path d='M44 0V150L84 190V260'/><path d='M0 210H40'/><circle cx='330' cy='30' r='5' fill='#070A0F'/><circle cx='84' cy='190' r='5' fill='#070A0F'/><circle cx='40' cy='210' r='4' fill='#070A0F'/><circle cx='120' cy='70' r='3' fill='#4DA3FF' fill-opacity='0.5'/></svg>")
const CIRCUITO_ABAJO = svgUrl("<svg xmlns='http://www.w3.org/2000/svg' width='440' height='260' viewBox='0 0 440 260' fill='none' stroke='#4DA3FF' stroke-opacity='0.32' stroke-width='2'><path d='M440 190H320L280 230H110'/><path d='M396 260V110L356 70V0'/><path d='M440 50H400'/><circle cx='110' cy='230' r='5' fill='#070A0F'/><circle cx='356' cy='70' r='5' fill='#070A0F'/><circle cx='400' cy='50' r='4' fill='#070A0F'/><circle cx='320' cy='190' r='3' fill='#4DA3FF' fill-opacity='0.5'/></svg>")
const PALOMITA = svgUrl("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='#FFB547' stroke-width='3.6' stroke-linecap='round' stroke-linejoin='round'><path d='M4 12.5l5.2 5.2L20 6.8'/></svg>")
const CRUZ = svgUrl("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='#FF7A7A' stroke-width='3.6' stroke-linecap='round'><path d='M6 6l12 12M18 6L6 18'/></svg>")
const DUDA = svgUrl("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='#9AA3B8' stroke-width='3.2' stroke-linecap='round' stroke-linejoin='round'><path d='M8.5 8.5a3.6 3.6 0 1 1 5.2 3.2c-1.1.6-1.7 1.4-1.7 2.6v.7'/><circle cx='12' cy='19' r='0.6' fill='#9AA3B8'/></svg>")

const estilo = `
html, body { margin: 0; background: #070A0F; }
body { color: #F5F7FF; font-family: "Segoe UI", "Segoe UI Variable", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif; font-weight: 700; line-height: 1.3; display: block; min-height: 100vh; -webkit-text-size-adjust: 100%; }
.cielo, .cielo::before, .cielo::after { position: fixed; top: 0; right: 0; bottom: 0; left: 0; pointer-events: none; }
.cielo { z-index: 0; opacity: 0.6; background-image:
  radial-gradient(1.6px 1.6px at 24px 36px, rgba(245,247,255,0.8), transparent),
  radial-gradient(1.2px 1.2px at 170px 96px, rgba(245,247,255,0.6), transparent),
  radial-gradient(1.6px 1.6px at 96px 180px, rgba(154,163,184,0.8), transparent),
  radial-gradient(1.2px 1.2px at 230px 236px, rgba(245,247,255,0.5), transparent),
  radial-gradient(2px 2px at 64px 280px, rgba(242,230,58,0.45), transparent);
  background-size: 250px 250px, 310px 310px, 270px 270px, 340px 340px, 420px 420px; }
.cielo::before { content: ""; background: ${CIRCUITO} left top no-repeat; background-size: 440px 260px; }
.cielo::after { content: ""; background: ${CIRCUITO_ABAJO} right bottom no-repeat; background-size: 440px 260px; }
.escena { position: relative; z-index: 1; box-sizing: border-box; max-width: 1680px; min-height: 100vh; margin: 0 auto; padding: 48px 72px 28px; display: flex; flex-direction: column; }
.chip { display: inline-block; align-self: flex-start; margin: 0; padding: 8px 22px; border: 2px solid rgba(154,163,184,0.55); border-radius: 999px; color: #F5F7FF; font-size: 24px; }
.nombre { margin: 28px 0 0; color: #F2E63A; font-size: 64px; font-size: clamp(48px, 7.4vw, 150px); line-height: 1.04; letter-spacing: -0.01em; overflow-wrap: anywhere; }
.nombre.largo { font-size: 56px; font-size: clamp(40px, 5vw, 100px); }
.nombre.muy-largo { font-size: 44px; font-size: clamp(32px, 3.7vw, 72px); }
.veredicto { position: relative; display: inline-flex; align-items: center; align-self: flex-start; margin: 30px 0 0; padding: 14px 40px 14px 30px; border: 4px solid currentColor; border-radius: 999px; font-size: 52px; font-size: clamp(36px, 4.4vw, 86px); line-height: 1; letter-spacing: 0.04em; }
.veredicto::before { content: ""; width: 0.9em; height: 0.9em; margin-right: 0.32em; background-position: center; background-repeat: no-repeat; background-size: contain; }
.veredicto::after { content: ""; position: absolute; top: -4px; right: -4px; bottom: -4px; left: -4px; border: 4px solid currentColor; border-radius: 999px; opacity: 0; }
.libre { color: #FFB547; background: rgba(255,181,71,0.12); box-shadow: 0 0 36px rgba(255,181,71,0.35); }
.libre::before { background-image: ${PALOMITA}; }
.ocupado { color: #FF7A7A; background: rgba(255,122,122,0.12); box-shadow: 0 0 36px rgba(255,122,122,0.32); }
.ocupado::before { background-image: ${CRUZ}; }
.dudoso { color: #9AA3B8; background: rgba(154,163,184,0.12); box-shadow: 0 0 30px rgba(154,163,184,0.25); }
.dudoso::before { background-image: ${DUDA}; }
.porque { margin: 30px 0 0; max-width: 1500px; font-size: 24px; font-size: clamp(20px, 1.95vw, 38px); line-height: 1.32; }
.abajo { display: flex; flex-wrap: wrap; gap: 28px 64px; margin-top: 40px; }
.abajo h2 { margin: 0 0 14px; color: #9AA3B8; font-size: 20px; font-size: clamp(17px, 1.25vw, 24px); letter-spacing: 0.06em; text-transform: uppercase; }
.otros { flex: 0 1 auto; }
.otros ul { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 12px; }
.otros li { padding: 10px 22px; border: 2px solid rgba(255,181,71,0.75); border-radius: 14px; color: #FFB547; font-size: 26px; font-size: clamp(20px, 1.7vw, 32px); background: rgba(14,20,29,0.9); }
.google { flex: 1 1 520px; min-width: 0; }
.google ol { list-style: none; margin: 0; padding: 0; }
.google li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 14px; margin: 0 0 12px; padding-left: 24px; position: relative; font-size: 21px; font-size: clamp(18px, 1.35vw, 26px); }
.google li::before { content: ""; position: absolute; left: 0; top: 0.5em; width: 10px; height: 10px; border-radius: 50%; background: #4DA3FF; box-shadow: 0 0 10px rgba(77,163,255,0.8); }
.google a { color: #F5F7FF; text-decoration: none; border-bottom: 2px solid rgba(77,163,255,0.7); overflow-wrap: anywhere; }
.google .sitio { color: #9AA3B8; font-size: 0.8em; }
.pie { margin: auto 0 0; padding-top: 36px; color: #9AA3B8; font-size: 15px; font-weight: 600; line-height: 1.5; }
.pie span { color: #4DA3FF; }
@keyframes subir { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }
@keyframes golpe { 0% { opacity: 0; transform: scale(1.7); } 55% { opacity: 1; transform: scale(0.94); } 78% { transform: scale(1.03); } 100% { opacity: 1; transform: scale(1); } }
@keyframes aro { 0% { opacity: 0.9; transform: scale(1); } 100% { opacity: 0; transform: scale(1.35, 1.7); } }
@media (prefers-reduced-motion: no-preference) {
  .chip { animation: subir 0.5s ease-out both; }
  .nombre { animation: subir 0.6s ease-out 0.1s both; }
  .veredicto { animation: golpe 0.55s cubic-bezier(0.2, 0.9, 0.3, 1.25) 0.55s both; }
  .veredicto::after { animation: aro 0.9s ease-out 0.85s 1 both; }
  .porque { animation: subir 0.6s ease-out 1.05s both; }
  .abajo { animation: subir 0.6s ease-out 1.3s both; }
}
@media (max-width: 700px) {
  .escena { padding: 28px 16px 20px; }
  .chip { font-size: 16px; padding: 6px 16px; }
  .cielo::before, .cielo::after { background-size: 220px 130px; opacity: 0.7; }
  .nombre { margin-top: 20px; font-size: 44px; line-height: 1.08; }
  .nombre.largo { font-size: 34px; }
  .nombre.muy-largo { font-size: 28px; }
  .veredicto { margin-top: 22px; padding: 10px 26px 10px 20px; font-size: 32px; border-width: 3px; }
  .porque { margin-top: 22px; font-size: 19px; }
  .abajo { margin-top: 28px; gap: 24px; }
  .abajo h2 { font-size: 14px; }
  .otros li { font-size: 18px; padding: 8px 14px; }
  .google li { font-size: 17px; }
  .pie { font-size: 12px; }
}
`

const datos = $('Resumir resultados').first().json
const texto = String($input.first().json.text || '').replace(/\*/g, '')
let veredicto = linea(texto, 'VEREDICTO').toUpperCase().replace(/[^A-ZÁÉÍÓÚ]/g, '')
if (['LIBRE', 'OCUPADO', 'DUDOSO'].indexOf(veredicto) === -1) veredicto = 'DUDOSO'
const porque = linea(texto, 'POR QU[ÉE]')
const otros = linea(texto, 'OTROS NOMBRES').split(',').map(function (x) { return x.trim().replace(/\.$/, '') }).filter(Boolean).slice(0, 3)
const enlaces = datos.enlaces.filter(function (e) { return enlaceSeguro(e.enlace) }).map(function (e) {
  const u = enlaceSeguro(e.enlace)
  const s = sitio(u)
  // Los enlaces de Google pasan por google.com: ahí el sitio no dice nada y no se muestra.
  return '<li><a href="' + esc(u) + '" target="_blank" rel="noopener">' + esc(e.titulo) + '</a>' + (s && !/(^|\.)google\./i.test(s) ? '<span class="sitio">' + esc(s) + '</span>' : '') + '</li>'
}).join('')

// Un nombre largo baja de tamaño para que el veredicto siga a la vista.
const largo = String(datos.nombre || '').length
const html = '<style>' + estilo + '</style>' +
  '<div class="cielo" aria-hidden="true"></div>' +
  '<main class="escena">' +
  '<p class="chip">¿Ya existe tu nombre?</p>' +
  '<h1 class="nombre' + (largo > 32 ? ' muy-largo' : largo > 16 ? ' largo' : '') + '">' + esc(datos.nombre) + '</h1>' +
  '<p class="veredicto ' + esc(veredicto.toLowerCase()) + '">' + esc(veredicto) + '</p>' +
  '<p class="porque">' + esc(porque) + '</p>' +
  '<div class="abajo">' +
  (otros.length ? '<section class="otros"><h2>Otros nombres</h2><ul>' + otros.map(function (o) { return '<li>' + esc(o) + '</li>' }).join('') + '</ul></section>' : '') +
  (enlaces ? '<section class="google"><h2>Lo que encontró Google</h2><ol>' + enlaces + '</ol></section>' : '') +
  '</div>' +
  '<footer class="pie">Hecho con n8n + SerpApi + IA. Space Talks, NASA Space Apps Santa Cruz 2026. <span>github.com/nema1502/superpoderes-n8n</span></footer>' +
  '</main>'
return [{ json: { html: html, veredicto: veredicto, por_que: porque, otros_nombres: otros } }]
